// (Caution) OLD WAY: returns null — callers can forget null check
package com.bank.lookup.service;

import com.bank.lookup.dto.AccountResponse;
import com.bank.lookup.model.Account;
import com.bank.lookup.repository.AccountRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;

@Service
@RequiredArgsConstructor
@Slf4j
public class UnsafeLookupService {

    private final AccountRepository accountRepo;

    // (Avoid) Returns null — caller must remember to check!
    public Account findAccount(String accountId) {
        return accountRepo.findById(accountId).orElse(null);  // returns null if not found!
    }

    public AccountResponse lookupUnsafe(String accountId) {
        Account account = findAccount(accountId);

        // Without null check → NPE on account.getHolderName()!
        try {
            return new AccountResponse(accountId, account.getHolderName(),
                account.getBalance(), account.getStatus(), "UNSAFE (null-based)");
        } catch (NullPointerException e) {
            log.error(" NPE! Forgot null check for account: {}", accountId);
            return new AccountResponse(accountId, "NPE!", null, "ERROR",
                " NullPointerException — forgot to check null!");
        }
    }
}
