// (Recommended) NEW WAY: returns Optional — caller MUST handle absence
package com.bank.lookup.service;

import com.bank.lookup.dto.AccountResponse;
import com.bank.lookup.model.Account;
import com.bank.lookup.repository.AccountRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.Optional;

@Service
@RequiredArgsConstructor
@Slf4j
public class SafeLookupService {

    private final AccountRepository accountRepo;

    // (Recommended) Returns Optional — caller is FORCED to handle absence
    public Optional<Account> findAccount(String accountId) {
        return accountRepo.findById(accountId);  // JPA already returns Optional!
    }

    // ═══ Pattern 1: orElseThrow — fail fast with clear exception ═══
    public AccountResponse lookupOrThrow(String accountId) {
        Account account = findAccount(accountId)
            .orElseThrow(() -> new IllegalArgumentException("Account not found: " + accountId));

        return new AccountResponse(accountId, account.getHolderName(),
            account.getBalance(), account.getStatus(), "orElseThrow");
    }

    // ═══ Pattern 2: orElse — default value ═══
    public AccountResponse lookupWithDefault(String accountId) {
        String holderName = findAccount(accountId)
            .map(Account::getHolderName)       // Optional<String>
            .orElse("Unknown Customer");        // default if empty

        BigDecimal balance = findAccount(accountId)
            .filter(Account::isActive)         // Optional<Account> — empty if dormant
            .map(Account::getBalance)          // Optional<BigDecimal>
            .orElse(BigDecimal.ZERO);          // default if not found or dormant

        return new AccountResponse(accountId, holderName, balance,
            findAccount(accountId).map(Account::getStatus).orElse("NOT_FOUND"),
            "map + filter + orElse");
    }

    // ═══ Pattern 3: ifPresentOrElse — action based on presence ═══
    public AccountResponse lookupWithAction(String accountId) {
        StringBuilder result = new StringBuilder();

        findAccount(accountId).ifPresentOrElse(
            account -> result.append(account.getHolderName()).append(" — Rs.")
                .append(account.getBalance()),
            () -> result.append("Account ").append(accountId).append(" not found")
        );

        return new AccountResponse(accountId, result.toString(), null, null, "ifPresentOrElse");
    }

    // ═══ Pattern 4: Chained map + flatMap for nested data ═══
    public String getActiveAccountHolder(String accountId) {
        return findAccount(accountId)          // Optional<Account>
            .filter(Account::isActive)         // Optional<Account> — empty if dormant
            .map(Account::getHolderName)       // Optional<String>
            .map(String::toUpperCase)          // Optional<String>
            .orElse("NO ACTIVE ACCOUNT");
    }
}
