package com.bank.lookup.controller;

import com.bank.lookup.dto.AccountResponse;
import com.bank.lookup.service.*;
import lombok.RequiredArgsConstructor;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/v1/lookup")
@RequiredArgsConstructor
public class LookupController {

    private final UnsafeLookupService unsafeService;
    private final SafeLookupService safeService;

    @GetMapping("/unsafe/{accountId}")
    public AccountResponse unsafe(@PathVariable String accountId) {
        return unsafeService.lookupUnsafe(accountId);
    }

    @GetMapping("/safe/{accountId}")
    public AccountResponse safe(@PathVariable String accountId) {
        return safeService.lookupOrThrow(accountId);
    }

    @GetMapping("/default/{accountId}")
    public AccountResponse withDefault(@PathVariable String accountId) {
        return safeService.lookupWithDefault(accountId);
    }

    @GetMapping("/action/{accountId}")
    public AccountResponse withAction(@PathVariable String accountId) {
        return safeService.lookupWithAction(accountId);
    }
}
