// ─── File: src/test/java/com/bank/lookup/service/OptionalBasicsTest.java ───
package com.bank.lookup.service;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.Optional;
import static org.assertj.core.api.Assertions.*;

class OptionalBasicsTest {

    @Test
    void ofWrapsNonNull() {
        Optional<String> opt = Optional.of("RELIANCE");
        assertThat(opt.isPresent()).isTrue();
        assertThat(opt.get()).isEqualTo("RELIANCE");
    }

    @Test
    void ofThrowsOnNull() {
        assertThatThrownBy(() -> Optional.of(null))
            .isInstanceOf(NullPointerException.class);
    }

    @Test
    void ofNullableHandlesBoth() {
        Optional<String> present = Optional.ofNullable("TCS");
        Optional<String> absent = Optional.ofNullable(null);

        assertThat(present.isPresent()).isTrue();
        assertThat(absent.isEmpty()).isTrue();
    }

    @Test
    void mapTransformsIfPresent() {
        Optional<String> upper = Optional.of("reliance")
            .map(String::toUpperCase);
        assertThat(upper).contains("RELIANCE");

        Optional<String> empty = Optional.<String>empty()
            .map(String::toUpperCase);
        assertThat(empty).isEmpty();  // map on empty → empty
    }

    @Test
    void filterKeepsOnlyIfMatches() {
        Optional<Integer> high = Optional.of(780).filter(s -> s >= 650);
        Optional<Integer> low = Optional.of(490).filter(s -> s >= 650);

        assertThat(high).contains(780);
        assertThat(low).isEmpty();  // didn't pass filter → empty
    }

    @Test
    void orElseVsOrElseGet() {
        // orElse: default ALWAYS evaluated (even if present!)
        String result1 = Optional.of("RELIANCE").orElse(computeDefault());
        // computeDefault() WAS called (wasteful!) but result is "RELIANCE"

        // orElseGet: default evaluated ONLY if empty
        String result2 = Optional.of("RELIANCE").orElseGet(() -> computeDefault());
        // computeDefault() was NOT called — Supplier not invoked!

        assertThat(result1).isEqualTo("RELIANCE");
        assertThat(result2).isEqualTo("RELIANCE");
    }

    @Test
    void orElseThrowForFailFast() {
        assertThatThrownBy(() ->
            Optional.empty().orElseThrow(() -> new IllegalArgumentException("Not found!")))
            .isInstanceOf(IllegalArgumentException.class)
            .hasMessage("Not found!");
    }

    @Test
    void chainingMapAndFilter() {
        String name = Optional.of("Rajesh Kumar")
            .filter(n -> n.length() > 5)
            .map(String::toUpperCase)
            .orElse("UNKNOWN");
        assertThat(name).isEqualTo("RAJESH KUMAR");
    }

    private String computeDefault() { return "DEFAULT"; }
}
